window.JELLING_STONE_SVG = "data:image/svg+xml;base64,";
window.JELLING_CAD_MESHES = {"01_base_DRAFT.ply":"","02_lid_DRAFT.ply":"","03_LEGO_12x12_plate_DRAFT.ply":"","button_A_SW2_DRAFT.ply":"","button_B_SW3_DRAFT.ply":"","button_C_SW5_DRAFT.ply":"","button_D_SW6_DRAFT.ply":"","reference_buzzer_footprint.ply":"","reference_nrf_PCB.ply":"","reference_oled_PCB.ply":"","reference_oled_panel.ply":"","reference_switch_10.ply":"","reference_switch_11.ply":"","reference_switch_8.ply":"","reference_switch_9.ply":""};
window.decodeCADMesh = function(name) {
  var b64 = window.JELLING_CAD_MESHES[name];
  if (!b64) return null;
  var bin = atob(b64), len = bin.length, bytes = new Uint8Array(len);
  for (var i = 0; i < len; i++) bytes[i] = bin.charCodeAt(i);
  return bytes.buffer;
};